int distance(int a, int b)
{
    int counterValue = 0;
    int flagAIsBigger = 0;
    int smallerNumber = a;
    int largerNumber = b;

    if (a > b)
    {
        flagAIsBigger = 1;
        smallerNumber = b;
        largerNumber = a;
    }
    else
    {
        flagAIsBigger = 0;
        smallerNumber = a;
        largerNumber = b;
    }

    int totalValueSoFar = smallerNumber;
    while (totalValueSoFar < largerNumber)
    {
        counterValue = counterValue + 1;
        totalValueSoFar = totalValueSoFar + 1;
    }

    printf("%d", counterValue);
    return 0;
}
